1 | // node --test plans/_chk.test.mjs
2 | //
3 | // PORTABLE BY CONSTRUCTION. Nothing here reads a path outside the repo, so this
4 | // suite passes on a fresh clone on any machine.
5 | //
6 | // The regression corpus is the four REAL Bob exports in tools/fixtures/repo-{a,b}/
7 | // (checked in, run through tools/redact.mjs, zero username hits). The git side of
8 | // the join cannot be checked in - a .git directory carries the author's name and
9 | // email - so tools/fixtures/history.json records the real commit contents,
10 | // messages and committer timestamps, and buildRepo() replays them into a temp
11 | // directory. Same bytes, same times, same diffs; only the shas differ per run,
12 | // which is why the tests resolve a sha by commit message instead of hardcoding it.
13 | import { test } from 'node:test';
14 | import assert from 'node:assert/strict';
15 | import { execFileSync } from 'node:child_process';
16 | import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } from 'node:fs';
17 | import { tmpdir } from 'node:os';
18 | import path from 'node:path';
19 | import { fileURLToPath } from 'node:url';
20 | 
21 | import * as chk from './_chk.mjs';
22 | 
23 | const {
24 |   normalisePath, loadSessions, writtenFiles, classifyTools,
25 |   commitLog, commitForTask, attributeTask, assertUniqueCommits, survivingLines,
26 |   taskSurvival,
27 | } = chk;
28 | 
29 | const HERE = fileURLToPath(new URL('.', import.meta.url));
30 | const FIXTURES = fileURLToPath(new URL('../../tools/fixtures/', import.meta.url));
31 | const HISTORY = JSON.parse(readFileSync(path.join(FIXTURES, 'history.json'), 'utf8'));
32 | 
33 | // The workspace string as the redacted exports actually spell it. It is compared
34 | // as a STRING PREFIX against the _meta.changes keys - it is never opened - so the
35 | // replayed repo living somewhere else on disk is irrelevant to the join.
36 | const WS = 'file:c:\\Users\\USER\\bobtest';
37 | 
38 | const trash = [];
39 | process.on('exit', () => { for (const d of trash) rmSync(d, { recursive: true, force: true }); });
40 | 
41 | /** Replay one fixture history into a fresh temp repo. Returns { dir, sha(message) }. */
42 | function buildRepo(name) {
43 |   const dir = mkdtempSync(path.join(tmpdir(), `chk-${name}-`));
44 |   trash.push(dir);
45 |   const g = (...a) => execFileSync('git', a, { cwd: dir, encoding: 'utf8' });
46 |   g('init', '-q', '-b', 'main');
47 |   g('config', 'user.email', 'fixture@example.invalid');
48 |   g('config', 'user.name', 'fixture');
49 |   g('config', 'core.autocrlf', 'false'); // else every line differs from the export
50 |   for (const c of HISTORY[name]) {
51 |     for (const [f, body] of Object.entries(c.files)) {
52 |       mkdirSync(path.dirname(path.join(dir, f)), { recursive: true });
53 |       writeFileSync(path.join(dir, f), body);
54 |     }
55 |     g('add', '-A');
56 |     // Committer time is what commitLog() reads and what the join compares against
57 |     // task.updatedAt, so it has to be the real one, not "now".
58 |     const iso = new Date(c.ts * 1000).toISOString();
59 |     execFileSync('git', ['commit', '-qm', c.message], {
60 |       cwd: dir,
61 |       encoding: 'utf8',
62 |       env: { ...process.env, GIT_AUTHOR_DATE: iso, GIT_COMMITTER_DATE: iso },
63 |     });
64 |   }
65 |   const sha = (message) => {
66 |     const out = g('log', '--format=%H %s', 'HEAD').split('\n')
67 |       .find((l) => l.slice(41) === message);
68 |     assert.ok(out, `fixture history has no commit "${message}"`);
69 |     return out.slice(0, 40);
70 |   };
71 |   return { dir, sha };
72 | }
73 | 
74 | const A = buildRepo('repo-a');
75 | const B = buildRepo('repo-b');
76 | const SESSIONS_A = path.join(FIXTURES, 'repo-a');
77 | const SESSIONS_B = path.join(FIXTURES, 'repo-b');
78 | 
79 | const byId = (dir) => Object.fromEntries(loadSessions(dir).map((e) => [e.task.id.slice(0, 8), e]));
