82 | test('normalisePath decodes a real _meta.changes key to a repo-relative path', () => {
83 |   assert.equal(normalisePath('calc.py', WS), 'calc.py');
84 |   assert.equal(normalisePath('c:\\Users\\USER\\bobtest\\calc.py', WS), 'calc.py');
85 |   // The form Bob actually emits as a _meta.changes key: file:/// + percent-encoded
86 |   // drive colon + forward slashes + lowercase drive letter.
87 |   assert.equal(normalisePath('file:///c%3A/Users/USER/bobtest/calc.py', WS), 'calc.py');
88 | });
