90 | test('writtenFiles collects every _meta.changes entry, one per message', () => {
91 |   const e = byId(SESSIONS_B).ef4ccef5;
92 |   // Two apply_diff results in two separate messages, one file key each.
93 |   assert.deepEqual(writtenFiles(e, e._workspace), ['a.py', 'b.py']);
94 | 
95 |   // Bob emits ONE _meta.changes entry per edit-tool result, each with exactly one
96 |   // key; multiplicity lives ACROSS messages. Reading only the last one loses edits.
97 |   const changesOnly = {
98 |     task: { id: 'y', updatedAt: 1 },
99 |     messages: [
100 |       { data: { _meta: { changes: { 'file:///c%3A/Users/USER/bobtest/calc.py': {} } } } },
101 |       { data: { _meta: { changes: { 'file:///c%3A/Users/USER/bobtest/sub/other.py': {} } } } },
102 |     ],
103 |   };
104 |   assert.deepEqual(writtenFiles(changesOnly, WS), ['calc.py', 'sub/other.py']);
105 | });
