107 | test('write detection is permission-driven, not a hardcoded tool-name list', () => {
108 |   const e = byId(SESSIONS_B).ef4ccef5;
109 |   const { writes, unknownTools } = classifyTools(e, e._workspace);
110 |   // glob and FindSymbol are permission:"read" with arguments.path === undefined.
111 |   assert.deepEqual(writes.map((w) => w.path).sort(), ['a.py', 'b.py']);
112 |   assert.deepEqual(unknownTools, []);
113 | });
114 | 
115 | test('a tool whose write status cannot be decided is counted, not dropped', () => {
116 |   const entry = {
117 |     task: { id: 'x', updatedAt: 1 },
118 |     messages: [
119 |       { data: { toolUsage: { signature: { name: 'mystery_writer', arguments: {} }, permission: 'edit' } } },
120 |       { data: { toolUsage: { signature: { name: 'future_tool', arguments: { path: 'z.py' } }, permission: 'sudo' } } },
121 |     ],
122 |   };
123 |   const { writes, unknownTools } = classifyTools(entry, null);
124 |   assert.deepEqual(writes, []);
125 |   assert.deepEqual(unknownTools.map((u) => u.name).sort(), ['future_tool', 'mystery_writer']);
126 | });
127 | 
128 | // ---------------------------------------------------------------- BUG 1
129 | test('commitForTask refuses a commit that contains none of the lines Bob wrote', () => {
130 |   const commits = commitLog(A.dir);
131 |   const e = byId(SESSIONS_A).da0e0ddc;
132 |   // Bob added a divide-by-zero guard that was never committed. The next commit in
133 |   // time is "C: human rewrites Bob's docstring". Crediting it is the bug.
134 |   const c = commitForTask(commits, e.task.updatedAt, {
135 |     repo: A.dir, entry: e, windowMs: Infinity,
136 |   });
137 |   assert.equal(c, null);
138 | });
139 | 
140 | test('commitForTask still credits the commit that does carry Bob lines', () => {
141 |   const commits = commitLog(A.dir);
142 |   const e = byId(SESSIONS_A).d0259633;
143 |   const c = commitForTask(commits, e.task.updatedAt, { repo: A.dir, entry: e });
144 |   assert.equal(c.sha, A.sha('B: docstring on add (by Bob)'));
145 | });
146 | 
147 | test('commitForTask honours an upper time bound', () => {
148 |   const commits = commitLog(A.dir);
149 |   const e = byId(SESSIONS_A).d0259633; // its commit lands 198s later
150 |   assert.equal(commitForTask(commits, e.task.updatedAt,
151 |     { repo: A.dir, entry: e, windowMs: 10_000 }), null);
152 | });
