154 | test('a task with no joined commit reaches an unattributed bucket, never vanishes', () => {
155 |   const rows = [
156 |     ...loadSessions(SESSIONS_A).map((e) => attributeTask(A.dir, e)),
157 |     ...loadSessions(SESSIONS_B).map((e) => attributeTask(B.dir, e)),
158 |   ];
159 |   assert.equal(rows.length, 4, 'all four tasks must survive the pipeline');
160 |   const got = Object.fromEntries(rows.map((r) => [r.id.slice(0, 8), {
161 |     files: r.wroteFiles, sha: r.commit?.short ?? null, pct: r.survivalPct, why: r.unattributed,
162 |   }]));
163 |   assert.deepEqual(got, {
164 |     '1f84e13c': { files: [], sha: null, pct: null, why: 'no-files-written' },
165 |     'd0259633': {
166 |       files: ['calc.py'],
167 |       sha: A.sha('B: docstring on add (by Bob)').slice(0, 7),
168 |       pct: 0,
169 |       why: null,
170 |     },
171 |     'da0e0ddc': { files: ['calc.py'], sha: null, pct: null, why: 'no-matching-commit' },
172 |     'ef4ccef5': { files: ['a.py', 'b.py'], sha: null, pct: null, why: 'no-matching-commit' },
173 |   });
174 | });
175 | 
176 | test('two tasks claiming one commit is a hard failure, and the sha is printed', () => {
177 |   const dup = [
178 |     { id: 'aaa', commit: { sha: 'deadbeef' } },
179 |     { id: 'bbb', commit: { sha: 'deadbeef' } },
180 |   ];
181 |   assert.throws(() => assertUniqueCommits(dup), /deadbeef[\s\S]*aaa[\s\S]*bbb|aaa[\s\S]*bbb/);
182 |   assert.doesNotThrow(() => assertUniqueCommits([dup[0]]));
183 | });
