185 | test('a brace is not evidence of authorship', () => {
186 |   // The real corpus is Python, so it never exercises this: in a TS/TSX repo "}" is the
187 |   // most-added line, and matching on it lets any human commit that touches the same
188 |   // file be credited to Bob - collapsing the authorship half of the join. Synthetic,
189 |   // because no export on disk has a brace-only edit.
190 |   const entry = {
191 |     _workspace: 'file:c:\\repo',
192 |     task: { id: 'brace', workspace: 'file:c:\\repo', updatedAt: 1 },
193 |     messages: [{
194 |       data: {
195 |         toolUsage: { permission: 'edit', isError: false,
196 |           signature: { name: 'apply_diff', id: 't1', arguments: { path: 'a.ts' } } },
197 |         _meta: { changes: { 'file:///c%3A/repo/a.ts': {
198 |           before: 'const x = 1;\n',
199 |           // Bob's only NEW lines here are a brace and a short paren - no real content.
200 |           after: 'const x = 1;\nif (x) {\n}\n);\n',
201 |         } } },
202 |       },
203 |     }],
204 |   };
205 |   const bob = chk.bobAddedLines(entry, 'file:c:\\repo');
206 |   const lines = [...(bob.get('a.ts') ?? [])];
207 |   assert.ok(!lines.includes('}'), 'a bare } must not count as a Bob-authored line');
208 |   assert.ok(!lines.includes(');'), 'a bare ); must not count as a Bob-authored line');
209 |   assert.deepEqual(lines, ['if (x) {'], 'only the >=4-char line survives as evidence');
210 | });
211 | 
212 | // ---------------------------------------------------------------- git blame flags
213 | test('a whitespace-only reformat does not erase the authoring commit', () => {
214 |   const repo = mkdtempSync(path.join(tmpdir(), 'chk-blame-'));
215 |   const g = (...a) => execFileSync('git', a, { cwd: repo, encoding: 'utf8' });
216 |   try {
217 |     g('init', '-q', '-b', 'main');
218 |     g('config', 'user.email', 't@t'); g('config', 'user.name', 't');
219 |     g('config', 'core.autocrlf', 'false');
220 |     writeFileSync(path.join(repo, 'f.py'), 'def a():\n  return 1\n\ndef b():\n  return 2\n');
221 |     g('add', '-A'); g('commit', '-qm', 'bob writes f.py');
222 |     const sha = g('rev-parse', 'HEAD').trim();
223 |     // A formatter run: same lines, 4-space indent.
224 |     writeFileSync(path.join(repo, 'f.py'), 'def a():\n    return 1\n\ndef b():\n    return 2\n');
225 |     g('add', '-A'); g('commit', '-qm', 'black .');
226 |     assert.equal(survivingLines(repo, sha, 'f.py'), 5,
227 |       'without `git blame -w` a reformat collapses every task to ~0% survival');
228 |   } finally {
229 |     rmSync(repo, { recursive: true, force: true });
230 |   }
231 | });
232 | 
233 | // ------------------------------------------------- task-level vs commit-level
234 | test('survival counts the lines THIS TASK wrote, not every line its commit added', () => {
235 |   // The regression this guards, and it inverts rather than merely inflating:
236 |   // taskSurvival() used to take its denominator from addedLines(repo, sha) - every
237 |   // line the commit added - while README-DRAFT, the long description and
238 |   // USAGE-STATEMENT all promise "the lines that task wrote". On a commit holding
239 |   // 1 Bob line plus 9 human lines, a task whose contribution was FULLY REVERTED
240 |   // reported ~90% survived. No test covered a mixed-authorship commit, which is
241 |   // exactly how it shipped. bobLines comes back from commitForTask now.
242 |   const repo = mkdtempSync(path.join(tmpdir(), 'mixed-'));
243 |   trash.push(repo);
244 |   const g = (...a) => execFileSync('git', ['-C', repo, ...a], { encoding: 'utf8' });
245 |   g('init', '-q', '-b', 'main');
246 |   g('config', 'user.email', 't@t'); g('config', 'user.name', 't');
247 |   g('config', 'core.autocrlf', 'false');
248 | 
249 |   const BOB = 'def bob_helper(): return 42';
250 |   const HUMAN = Array.from({ length: 9 }, (_, i) => `def human_${i}(): return ${i}`);
251 | 
252 |   // One commit, mixed authorship: Bob's single line plus nine of the human's.
253 |   writeFileSync(path.join(repo, 'm.py'), [BOB, ...HUMAN].join('\n') + '\n');
254 |   g('add', '-A'); g('commit', '-qm', 'mixed authorship');
255 |   const sha = g('rev-parse', 'HEAD').trim();
256 | 
257 |   // Revert ONLY Bob's line. All nine human lines stay at HEAD.
258 |   writeFileSync(path.join(repo, 'm.py'), HUMAN.join('\n') + '\n');
259 |   g('add', '-A'); g('commit', '-qm', 'revert bob only');
260 | 
261 |   const entry = {
262 |     _workspace: repo,
263 |     task: { workspace: repo },
264 |     messages: [{ data: { _meta: { changes: {
265 |       [`file:///${repo.replace(/\\/g, '/')}/m.py`]: { before: '', after: BOB + '\n' },
266 |     } } } }],
267 |   };
268 | 
269 |   const commits = commitLog(repo);
270 |   const picked = commitForTask(commits, commits[0].timeMs, { repo, entry });
271 |   assert.ok(picked, 'the mixed commit contains a Bob line, so it must attribute');
272 |   assert.ok(picked.bobLines?.size, 'commitForTask must hand back the authored line set');
273 | 
274 |   const commitLevel = taskSurvival(repo, sha, ['m.py']);
275 |   const taskLevel = taskSurvival(repo, sha, ['m.py'], picked.bobLines);
276 | 
277 |   // Ground truth: Bob wrote 1 line, 0 of it survives -> 0%.
278 |   assert.equal(taskLevel.authored, 1, "denominator must be Bob's lines, not the commit's");
279 |   assert.equal(taskLevel.survived, 0);
280 |   assert.equal(taskLevel.pct, 0);
281 |   assert.equal(taskLevel.level, 'task');
282 | 
283 |   // And the old path really did report the opposite, which is why this test exists.
284 |   assert.ok(commitLevel.pct > 0.5,
285 |     'commit-level math inflates a fully-reverted task above 50% - the defect being guarded');
286 | });
