289 | test('no machine-specific absolute path survives in the shipped join code', () => {
290 |   // The regression this guards: the corpus used to be read from two absolute paths
291 |   // with the author's username in them. They existed on one laptop, so the suite
292 |   // was green here and 6 of 11 ENOENT'd in a clean clone - which is worse than a
