Contents of file tools/_chk.mjs:

1 | import { execFileSync } from 'node:child_process';
2 | import { readdirSync, readFileSync } from 'node:fs';
3 | import path from 'node:path';
4 | 
5 | /**
6 |  * DISPLAY LABEL ONLY - never a predicate. Across all four real exports `apply_diff`
7 |  * is the only write tool ever observed; the other three were guesses, and any tool
8 |  * not on a guessed list is silently counted as "wrote nothing". isWrite() below
9 |  * decides from the permission field instead.
10 |  */
11 | export const WRITE_TOOLS = new Set([
12 |   'apply_diff', 'write_file', 'insert_content', 'search_and_replace',
13 | ]);
14 | 
15 | /** How long after a task's last update a commit may still be that task's. */
16 | // ponytail: flat 2h window, a knob not a law. Widen it if the team batches commits;
17 | // the authorship test below is what actually keeps a human's commit out.
18 | export const DEFAULT_WINDOW_MS = 2 * 60 * 60 * 1000;
19 | 
20 | /**
21 |  * Turns anything Bob calls a path into a repo-relative forward-slash path.
22 |  * git speaks repo-relative forward slashes. Without this the join silently
23 |  * returns zero files and every survival number reads 0%.
24 |  *
25 |  * The two inputs are NOT the same shape and differ four ways at once:
26 |  *   task.workspace         "file:c:\\Users\\USER\\bobtest"                  (scheme + backslashes)
27 |  *   _meta.changes key      "file:///c%3A/Users/USER/bobtest/calc.py"       (scheme + slashes + %3A)
28 |  * So the scheme is stripped from BOTH sides, the key is percent-decoded, and the
29 |  * comparison is case-insensitive (the drive letter's case differs between them).
30 |  *
31 |  * arguments.path, by contrast, is a bare relative filename in all 14 tool calls of
32 |  * the four real exports - the absolute-path branch is defensive, not observed.
33 |  */
34 | export function normalisePath(p, repoRoot) {
35 |   if (!p) return null;
36 |   let s = String(p).replace(/^file:\/*/i, '');
37 |   try { s = decodeURIComponent(s); } catch { /* not percent-encoded; use as-is */ }
38 |   s = s.replace(/\\/g, '/');
39 |   if (repoRoot) {
40 |     const root = String(repoRoot)
41 |       .replace(/^file:\/*/i, '')
42 |       .replace(/\\/g, '/')
43 |       .replace(/\/+$/, '');
44 |     if (root && s.toLowerCase().startsWith(root.toLowerCase() + '/')) s = s.slice(root.length + 1);
45 |   }
46 |   return s.replace(/^\.\//, '').replace(/^\/+/, '');
47 | }
48 | 
49 | /** Reads every bob_sessions/*.json and flattens their tasks[] into one list. */
50 | export function loadSessions(dir) {
51 |   const out = [];
52 |   for (const f of readdirSync(dir).filter((f) => f.endsWith('.json')).sort()) {
53 |     let raw;
54 |     try {
55 |       raw = JSON.parse(readFileSync(path.join(dir, f), 'utf8'));
56 |     } catch (e) {
57 |       throw new Error(`bob_sessions/${f} is not valid JSON: ${e.message}`);
58 |     }
59 |     for (const entry of raw.tasks ?? []) {
60 |       out.push({ ...entry, _workspace: raw.workspace ?? null, _file: f });
61 |     }
62 |   }
63 |   // DEDUPE BY task.id. Bob tasks are resumable and the ritual exports "Current
64 |   // Task" every time, so re-opening a task to ask one follow-up produces a second
65 |   // file with the SAME task.id and a later updatedAt. Without this, totals.coins
66 |   // is inflated (and will not match the Bob panel at the H+11 checkpoint) and
67 |   // React sees duplicate keys in the table, scatter and context chart.
68 |   const byId = new Map();
69 |   for (const e of out) {
70 |     const id = e.task?.id;
71 |     if (!id) continue;
72 |     const prev = byId.get(id);
73 |     if (!prev || (e.task.updatedAt ?? 0) > (prev.task.updatedAt ?? 0)) byId.set(id, e);
74 |   }
75 |   return [...byId.values()];
76 | }
77 | 
78 | /**
79 |  * Splits a task's tool calls into writes and "could not tell". `permission` is a
80 |  * plain STRING ("read" | "edit") on toolUsage, one per tool-result message - it is
81 |  * NOT an object, so `permission.read` is undefined and any test on it is vacuous.
82 |  * The arguments.path guard is load-bearing: `glob` and `FindSymbol` are edit-less
83 |  * reads whose arguments.path is undefined.
84 |  */
85 | export function classifyTools(entry, repoRoot) {
86 |   const writes = [];
87 |   const unknownTools = [];
88 |   for (const m of entry.messages ?? []) {
89 |     const tu = m?.data?.toolUsage;
90 |     if (!tu) continue;
91 |     const sig = tu.signature ?? {};
92 |     const name = sig.name ?? '(unnamed)';
93 |     if (tu.permission === 'read') continue;
94 |     if (tu.permission !== 'edit') {
95 |       // A tool that admits what it could not attribute is more credible than one
96 |       // that reports 0%. Surfaced, never swallowed.
97 |       unknownTools.push({ name, reason: `unrecognised permission ${JSON.stringify(tu.permission)}` });
98 |       continue;
99 |     }
100 |     if (sig.isError === true) continue;
101 |     if (typeof sig.arguments?.path !== 'string') {
102 |       unknownTools.push({ name, reason: 'edit tool with no arguments.path' });
103 |       continue;
104 |     }
105 |     const p = normalisePath(sig.arguments.path, repoRoot);
106 |     if (p) writes.push({ name, path: p });
107 |   }
108 |   return { writes, unknownTools };
109 | }
110 | 
111 | /**
112 |  * Every file touched by a `_meta.changes` entry. Bob emits ONE entry per edit-tool
113 |  * RESULT, each an object with exactly one key; multiplicity appears ACROSS messages.
114 |  * Reading only the last change-bearing message loses edits, so scan them all.
115 |  */
116 | export function changedFiles(entry, repoRoot) {
117 |   const out = [];
118 |   for (const m of entry.messages ?? []) {
119 |     for (const key of Object.keys(m?.data?._meta?.changes ?? {})) {
120 |       const p = normalisePath(key, repoRoot);
121 |       if (p) out.push({ path: p, change: m.data._meta.changes[key] });
122 |     }
123 |   }
124 |   return out;
125 | }
126 | 
127 | /** JOIN #2: repo-relative paths this task successfully wrote to. */
128 | export function writtenFiles(entry, repoRoot) {
129 |   const seen = new Set(classifyTools(entry, repoRoot).writes.map((w) => w.path));
130 |   for (const c of changedFiles(entry, repoRoot)) seen.add(c.path);
131 |   return [...seen].sort();
132 | }
133 | 
134 | /**
135 |  * file -> the set of lines this task actually ADDED, from _meta.changes before/after.
136 |  * This is the evidence the authorship test runs on. A change with no before/after
137 |  * yields nothing, which makes the task unattributed rather than falsely credited.
138 |  */
139 | export function bobAddedLines(entry, repoRoot) {
140 |   const map = new Map();
141 |   for (const { path: f, change } of changedFiles(entry, repoRoot)) {
142 |     if (change?.after === undefined) continue;
143 |     const remaining = new Map();
144 |     for (const l of String(change.before ?? '').split('\n')) {
145 |       const k = l.trim();
146 |       if (k) remaining.set(k, (remaining.get(k) ?? 0) + 1);
147 |     }
148 |     const set = map.get(f) ?? new Set();
149 |     for (const l of String(change.after).split('\n')) {
150 |       const k = l.trim();
151 |       if (!k) continue;
152 |       const n = remaining.get(k) ?? 0;
153 |       if (n > 0) remaining.set(k, n - 1);
154 |       // Candidate lines under 4 chars are not evidence of authorship: "}", "{", ");"
